// Build a lookup map: owner_id + metal_type -> rate_per_gram
const rates = $('Get Current Metal Rates').all().map(r => r.json);
const rateMap = {};
rates.forEach(r => {
  const key = `${r.owner_id}::${r.metal_type}`;
  rateMap[key] = Number(r.rate_per_gram);
});

// Helper: derive rate from 999 base if exact purity not found
function resolveRate(ownerId, metalType) {
  const exactKey = `${ownerId}::${metalType}`;
  if (rateMap[exactKey]) return rateMap[exactKey];

  const isGold   = metalType.startsWith('gold');
  const isSilver = metalType.startsWith('silver');
  const baseKey  = isGold   ? `${ownerId}::gold_999`
                 : isSilver ? `${ownerId}::silver_999`
                 : null;
  if (!baseKey || !rateMap[baseKey]) return 0;

  const targetPurity = Number(metalType.split('_')[1]) || 0;
  return rateMap[baseKey] * (targetPurity / 999);
}

// Calculate new price for each product
const products = $('Get Dynamic-Price Products').all().map(p => p.json);
const results = [];

for (const p of products) {
  const rate = resolveRate(p.owner_id, p.metal_type);
  if (!rate) continue;  // no rate available — skip this product

  const grams       = Number(p.metal_weight_grams);
  const wastage     = Number(p.wastage_percent  || 0) / 100;
  const metalCost   = rate * grams * (1 + wastage);

  const makingMode  = p.making_charge_type  || 'percentage';
  const makingVal   = Number(p.making_charge_value || 0);
  let makingCost = 0;
  if      (makingMode === 'percentage') makingCost = metalCost * makingVal / 100;
  else if (makingMode === 'per_gram')   makingCost = makingVal * grams;
  else                                  makingCost = makingVal; // flat

  const stone    = Number(p.stone_value_inr   || 0);
  const diamond  = Number(p.diamond_value_inr || 0);
  const hallmark = Number(p.hallmark_charge   || 45);

  const newPrice = Math.round(metalCost + makingCost + stone + diamond + hallmark);

  results.push({
    id:        p.id,
    owner_id:  p.owner_id,
    newPrice,
    metalCost: Math.round(metalCost),
    rate,
  });
}

return results.map(r => ({ json: r }));
